/* In-memory illustration sandbox. Never writes Dexcom, records, timers or rewards. */
(function(root){'use strict';let active=false,value=112,mode='current',index=0;
function connection(now){return {connected:mode!=='missing',error:null,reading:mode==='missing'?null:{value,unit:'mg/dL',sensor:'G7',status:'ok',simulated:true,timestamp:new Date(now-(mode==='stale'?root.DiaContext.STALE_MS+1:0)).toISOString(),stale:mode==='stale'}};}
function sample(band,t){const v=band==='low'?Math.min(t.low,401):band==='high'?Math.max(t.high,39):(Math.max(39,t.low)+Math.min(401,t.high))/2;const s=root.DiaContext.readingState({connected:true,reading:{value:v,unit:'mg/dL',sensor:'G7',timestamp:new Date().toISOString()}},t);return s.valid&&s.band===band?v:null;}
function selection(now=Date.now()){const c=connection(now),d=root.DiaContext.createDirector(),reduced=!!root.matchMedia?.('(prefers-reduced-motion: reduce)').matches;d.select({connection:c,thresholds:state.thresholds,now,baseAction:'Idle'});return {status:root.DiaContext.readingState(c,state.thresholds,now),pose:d.select({connection:c,thresholds:state.thresholds,now:now+2500+(index%3)*(reduced?90000:6000),baseAction:'Idle',reducedMotion:reduced})};}
function draw(){if(!active)return;const canvas=document.querySelector('#glucose-demo-canvas');if(!canvas)return;const {status,pose}=selection();paintWorld(canvas,state.equipped.Rooms||'cozy',state.equipped,status.band,pose.action,false,false,Date.now());document.querySelector('#glucose-demo-status').textContent='DEMO · '+(status.valid?(status.band==='range'?'In range':status.band==='low'?'Low':'High')+' · '+value+' mg/dL · '+pose.label:'Current preview data unavailable ('+status.reason+'); neutral buddy.')+' Fictional illustration, not a symptom or treatment instruction.';document.querySelector('#demo-glucose-number').value=value;document.querySelector('#demo-glucose-slider').value=value;document.querySelector('#demo-emote-next').disabled=!status.valid;document.querySelector('#demo-emote-count').textContent=status.valid?'Pose '+(index%3+1)+' of 3':'Neutral pose';}
function exit(close=true){active=false;value=112;mode='current';index=0;const box=document.querySelector('#glucose-demo-widget');if(box&&close){box.open=false;box.querySelector('summary').focus();}const note=document.querySelector('#glucose-demo-restored');if(note){const s=root.DiaContext.readingState(dexcom,state.thresholds);note.textContent=s.valid?'Normal Dexcom sandbox view restored (simulated provider readings).':'Normal view: current Dexcom data is unavailable; see the last update and connection status.';}}
function mount(){const host=document.querySelector('.home-world-column');if(!host||document.querySelector('#glucose-demo-widget'))return;active=false;value=112;mode='current';index=0;const t=state.thresholds;const box=document.createElement('details');box.id='glucose-demo-widget';box.className='card glucose-demo-widget';box.innerHTML=`<summary>Demo — simulated glucose <span>Open character preview</span></summary><div class="glucose-demo-body"><p>Illustration preview only. The normal buddy, glucose guidance, records, notifications, rewards and real meal timer are unchanged.</p><p>Parent thresholds: low at or below ${t.low} mg/dL; high at or above ${t.high} mg/dL. Between these is in range. Provider-compatible preview values: 39–401 mg/dL.</p><label for="demo-glucose-slider">Simulated glucose (mg/dL)</label><input id="demo-glucose-slider" type="range" min="39" max="401" step="0.1" value="${value}"><label for="demo-glucose-number">Glucose value (mg/dL)<input id="demo-glucose-number" type="number" min="39" max="401" step="0.1" value="${value}"></label><div class="demo-actions">${['low','range','high'].map(b=>`<button class="secondary" data-glucose-sample="${b}" ${sample(b,t)===null?'disabled':''}>${b==='range'?'In range':b==='low'?'Low':'High'}</button>`).join('')}<button class="secondary" data-glucose-mode="missing">Preview missing data</button><button class="secondary" data-glucose-mode="stale">Preview stale data</button></div><small>Quick choices are unavailable when a threshold has no matching sample in the supported preview range.</small><p id="glucose-demo-status" role="status"></p><canvas id="glucose-demo-canvas" width="640" height="400" aria-label="DEMO: simulated glucose character preview"></canvas><div class="demo-actions"><button class="secondary" id="demo-emote-next">Next emote</button><span id="demo-emote-count"></span><button class="secondary" id="demo-glucose-exit">Exit demo</button></div><p>This explicit preview cycles all poses even if ordinary contextual illustrations are turned off. The normal buddy still follows that parent preference and reduced-motion rendering.</p></div>`;host.appendChild(box);const note=document.createElement('p');note.id='glucose-demo-restored';note.className='helper';host.appendChild(note);box.addEventListener('toggle',()=>{if(box.open){active=true;draw();}else exit(false);});const change=e=>{const raw=e.target.value,n=Number(raw);if(!raw.trim()||!Number.isFinite(n)||n<39||n>401){document.querySelector('#glucose-demo-status').textContent='Enter a simulated value from 39 to 401 mg/dL.';return;}value=n;mode='current';index=0;active=true;draw();};box.querySelectorAll('input').forEach(el=>el.oninput=change);box.querySelectorAll('[data-glucose-sample]').forEach(b=>b.onclick=()=>{value=sample(b.dataset.glucoseSample,state.thresholds);mode='current';index=0;draw();});box.querySelectorAll('[data-glucose-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.glucoseMode;index=0;draw();});box.querySelector('#demo-emote-next').onclick=()=>{index++;draw();};box.querySelector('#demo-glucose-exit').onclick=()=>exit();}
root.DiaGlucoseDemo={mount,exit,draw,sample,selection,isActive:()=>active,open(){if(page!=='home')go('home');const box=document.querySelector('#glucose-demo-widget');if(box){box.open=true;active=true;draw();document.querySelector('#demo-glucose-number').focus();}}};
})(window);
